from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class LiquidityScreenedEqualWeighting(Strategy):
    rationale = (
        "Liquidity screening can reduce transaction costs and improve execution quality. "
        "An equal-weighted portfolio of highly liquid stocks can provide a diversified and robust performance."
    )

    def __init__(self, liquidity_window: int = 30) -> None:
        self._liquidity_window = liquidity_window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._liquidity_window)
        if history.is_empty():
            return Signal(information_available_at=stamp, weights={})

        volumes = history.select(pl.col("volume").sum().alias("total_volume"))
        liquidity_ranks = (
            volumes.with_columns(
                (pl.col("total_volume") / pl.col("total_volume").sum()).alias("liquidity_ratio")
            )
            .sort("liquidity_ratio", descending=True)
            .select(["symbol"])
            .head(10)["symbol"]
            .to_list()
        )

        if not liquidity_ranks:
            return Signal(information_available_at=stamp, weights={})

        weight = 1.0 / len(liquidity_ranks)
        return Signal(
            information_available_at=stamp,
            weights={s: weight for s in liquidity_ranks},
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max().cast(pl.Date)
    assert isinstance(newest, date)
    return newest
